#define _BW(N) __attribute__((C2RTL_bit_width(N))) 
#define _T(N) __attribute__((C2RTL_type(N))) 
#define _TOP(N) __attribute__((C2RTL_top_function(N))) 

typedef unsigned short UINT16 _BW(16), UINT10 _BW(10); 
typedef signed short SINT16 _BW(16), SINT10 _BW(10); 
typedef UINT16 ST_UINT16 _T(state), M_UINT16 _T(memory); 
typedef SINT16 SINT10; 
typedef UINT10 ST_UINT10 _T(state), M_UINT10 _T(memory);
attribute((C2RTL_bit_width(N)))：ビット幅属性を typedef 名に付与する。上記 の例では、UINT10, SINT10 に対して 10 ビット幅属性を付与しており、これらを継承 する ST_UINT10, M_UINT10 についても同じ 10 ビット幅属性が付与される。また、 UINT16, SINT16 に対しては 16 ビット幅属性を付与しており、これらを継承する ST_UINT16, M_UINT16 についても同じ 16 ビット幅属性が付与される。なお、ビット 幅 N が C++テンプレートの整数パラメータの場合、C2RTL_bit_width(“N”)と表記する。

What is this?
符号拡張するための関数
/**

 * @brief 符号拡張するための関数

 *

 * @tparam BW ビット幅

 * @param d 入力された値

 * @return int 符号拡張された値

 */

template&lt;int BW&gt; static int signExtend(int d){

    int d0 = d &amp; MaskBits32(BW);

    int dSext = (d0 &gt;&gt; (BW - 1)) ? (0xffffffff &lt;&lt; (BW - 1)) : 0;

    return dSext | d0;

}

